typedef GtkWidget *(*widget_ctor)(void);

static GtkWidget *with_border(widget_ctor make) {
    GtkWidget *w = make();                     /* wrap the constructor, not the widget */
    gtk_widget_add_css_class(w, "bordered");   /* no component type to compose around */
    return w;
}

